    context::RuleContext, declare_rule, Ast, Rule, RuleDiagnostic, RuleSource, RuleSourceKind,
};
use biome_console::markup;
use biome_css_syntax::{AnyCssDeclarationName, AnyCssDimension, CssFunction, CssSyntaxKind};
use biome_rowan::{AstNode, SyntaxNodeCast, TextRange};

declare_rule! {
    /// Disallow unknown CSS units.
    ///
    /// For details on known CSS units, see the [MDN web docs](https://developer.mozilla.org/en-US/docs/Learn/CSS/Building_blocks/Values_and_units#numbers_lengths_and_percentages).
    ///
    /// ## Examples
    ///
    /// ### Invalid
    ///
    /// ```css,expect_diagnostic
    /// a {
    ///   width: 10pixels;
    /// }
    /// ```
    ///
    /// ```css,expect_diagnostic
    /// a {
    ///   width: calc(10px + 10pixels);
    /// }
    /// ```
    ///
    /// ### Valid
    ///
    /// ```css
    /// a {
    ///   width: 10px;
    /// }
    /// ```
    ///
    /// ```css
    /// a {
    ///   width: 10Px;
    /// }
    /// ```
    ///
    pub NoUnknownUnit {
        version: "next",
        name: "noUnknownUnit",
        recommended: true,
        sources: &[RuleSource::Stylelint("unit-no-unknown")],
        source_kind: RuleSourceKind::SameLogic,
    }
}

pub struct NoUnknownUnitState {
    unit: String,
    span: TextRange,
}

impl Rule for NoUnknownUnit {
    type Query = Ast<AnyCssDimension>;
    type State = NoUnknownUnitState;
    type Signals = Option<Self::State>;
    type Options = ();

    fn run(ctx: &RuleContext<Self>) -> Option<Self::State> {
        let node = ctx.query();

        let unit_token = match node {
            // A regular dimension already has a known unit, so the only unit
            // that needs additional checking is `x`, which is a valid
            // resolution unit but is meaningless in any other context.
            AnyCssDimension::CssRegularDimension(dimension) => {
                let unit_token = dimension.unit_token().ok()?;
                let unit = unit_token.text_trimmed();

                // The `x` unit is used for resolutions (e.g. `image-set()`,
                // the `image-resolution` property, or `resolution` media
                // features). Outside of these contexts it should be treated
                // as an unknown unit.
                if unit.eq_ignore_ascii_case("x")
                    && !is_in_resolution_context(dimension.syntax())
                {
                    unit_token
                } else {
                    return None;
                }
            }
            AnyCssDimension::CssUnknownDimension(dimension) => dimension.unit_token().ok()?,
            // Percentages are always valid.
            AnyCssDimension::CssPercentage(_) => return None,
        };

        Some(NoUnknownUnitState {
            unit: unit_token.text_trimmed().to_string(),
            span: unit_token.text_trimmed_range(),
        })
    }

    fn diagnostic(_: &RuleContext<Self>, state: &Self::State) -> Option<RuleDiagnostic> {
        Some(
            RuleDiagnostic::new(
                rule_category!(),
                state.span,
                markup! {
                    "Unexpected unknown unit: "<Emphasis>{state.unit}</Emphasis>
                },
            )
            .note(markup! {
                "See "<Hyperlink href="https://developer.mozilla.org/en-US/docs/Learn/CSS/Building_blocks/Values_and_units#lengths">"MDN web docs"</Hyperlink>" for more details."
            })
            .footer_list(
                markup! {
                    "Use a known unit instead, such as:"
                },
                &["px", "em", "rem", "etc."],
            ),
        )
    }
}

/// The media feature names in which the `x` resolution unit is allowed.
const RESOLUTION_MEDIA_FEATURE_NAMES: [&str; 3] =
    ["resolution", "min-resolution", "max-resolution"];

/// Returns `true` when the given node is nested inside a context in which the
/// `x` resolution unit is valid.
fn is_in_resolution_context(node: &biome_css_syntax::CssSyntaxNode) -> bool {
    for ancestor in node.ancestors().skip(1) {
        match ancestor.kind() {
            CssSyntaxKind::CSS_FUNCTION => {
                let Some(function) = ancestor.cast::<CssFunction>() else {
                    continue;
                };
                let Ok(name) = function.name() else {
                    continue;
                };
                let Ok(name_token) = name.value_token() else {
                    continue;
                };
                // Handles `image-set()` as well as vendor prefixed variants
                // such as `-webkit-image-set()`.
                if name_token
                    .text_trimmed()
                    .to_ascii_lowercase()
                    .ends_with("image-set")
                {
                    return true;
                }
            }
            CssSyntaxKind::CSS_GENERIC_PROPERTY => {
                if let Some(name) = generic_property_name(&ancestor) {
                    if name.eq_ignore_ascii_case("image-resolution") {
                        return true;
                    }
                }
            }
            CssSyntaxKind::CSS_QUERY_FEATURE_PLAIN => {
                if let Some(name) = query_feature_plain_name(&ancestor) {
                    if RESOLUTION_MEDIA_FEATURE_NAMES
                        .iter()
                        .any(|feature| feature.eq_ignore_ascii_case(&name))
                    {
                        return true;
                    }
                }
            }
            _ => {}
        }
    }

    false
}

fn generic_property_name(node: &biome_css_syntax::CssSyntaxNode) -> Option<String> {
    let property = node.clone().cast::<biome_css_syntax::CssGenericProperty>()?;
    let name = property.name().ok()?;
    declaration_name_text(&name)
}

fn declaration_name_text(name: &AnyCssDeclarationName) -> Option<String> {
    let token = match name {
        AnyCssDeclarationName::CssIdentifier(identifier) => identifier.value_token().ok()?,
        AnyCssDeclarationName::CssDashedIdentifier(identifier) => identifier.value_token().ok()?,
    };
    Some(token.text_trimmed().to_string())
}

fn query_feature_plain_name(node: &biome_css_syntax::CssSyntaxNode) -> Option<String> {
    let feature = node
        .clone()
        .cast::<biome_css_syntax::CssQueryFeaturePlain>()?;
    let name = feature.name().ok()?;
    let token = name.value_token().ok()?;
    Some(token.text_trimmed().to_string())
}
